def skip_format_url(format_, url):
    """
    Checks whether a give format/url should be skipped and not downloaded.

    @param format_: Filename format (extension).
    @type format_: str (e.g. html, txt, zip, pdf)

    @param url: URL.
    @type url: str

    @return: True if format/url should be skipped, False otherwise.
    @rtype bool
    """
    # Skip PDFs
    if format_ == "pdf":
        return True

    # Skip URLs with certain words
    skip_words = ["/login", "/register", "/account", "/signup"]
    for word in skip_words:
        if word in url:
            return True

    # Skip URLs with certain extensions
    skip_extensions = ["/edit", "/delete", "/view", "/edit/", "/delete/", "/view/"]
    for extension in skip_extensions:
        if extension in url:
            return True

    return False

