def get_url_format(url):
    """
    Gets the format of a given URL.

    @param url: URL.
    @type url: str

    @return: Format of the URL (extension).
    @rtype str
    """
    return url.split(".")[-1]


def get_url_domain(url):
    """
    Gets the domain of a given URL.

    @param url: URL.
    @type url: str

    @return: Domain of the URL.
    @rtype str
    """
    return url.split("/")[2]


def get_url_filename(url):
    """
    Gets the filename of a given URL.

    @param url: URL.
    @type url: str

    @return: Filename of the URL.
    @rtype str
    """
    return url.split("/")[-1]


def get_url_path(url):
    """
    Gets the path of a given URL.

    @param url: URL.
    @type url: str

    @return: Path of the URL.
    @rtype str
    """
    return "/".join(url.split("/")[3:-1])


